function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}
function button(text,fn,cls=''){const b=el('button',cls,tr(text));b.type='button';b.addEventListener('click',fn);return b;}
function localizedUrl(path){const url=new URL(path,location.href);if(cfg.lang==='ar')url.searchParams.set('lang','ar_SA');else if(new URL(location.href).searchParams.has('lang'))url.searchParams.set('lang','en_US');return url.pathname+url.search+url.hash;}
document.querySelectorAll('.cb-top a').forEach(a=>a.href=localizedUrl(a.getAttribute('href')));
function link(text,url,cls=''){const a=el('a',cls,tr(text));a.href=localizedUrl(url);return a;}
function note(text){status.textContent=tr(text);}
async function api(action,payload,query={},signal){if(payload&&liveSync)liveSync.invalidate();const options=payload?{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({token:cfg.token,action,payload:JSON.stringify(payload)})}:{cache:'no-store'};const url=payload?'boards_api.php':'boards_api.php?'+new URLSearchParams({action,token:cfg.token,board:cfg.board,q:search.value,archived:archiveGallery?1:0,customer:cfg.customer||0,general:cfg.mode==='general'?1:0,...query});if(signal)options.signal=signal;const response=await fetch(url,options);let data;try{data=await response.json();}catch(e){const error=new Error(response.status===403?'Access or session denied.':'Unable to load boards.');error.status=(response.status===200&&/text\/html/i.test(response.headers.get('Content-Type')||''))?401:response.status;throw error;}if(!response.ok||!data.ok){const error=new Error(data.error||'Unable to save.');error.status=response.status;throw error;}return data.data;}
async function load(){if(liveSync)liveSync.invalidate();root.setAttribute('aria-busy','true');if(!root.childElementCount)root.append(el('p','cb-empty',wsText('جارٍ تحميل اللوحات…','Loading boards…')));try{if(cfg.mode==='deleted'){gallery=await api('deleted_boards');state=null;renderDeletedBoards();}else if(cfg.mode==='my'&&!sharedMode){state=await api('mywork');if(state.mode==='summary')renderSummary();else renderBoard();}else if(sharedMode){const data=await api('shared');state=null;renderShared(data.tasks);}else if(cfg.board){state=await api('workspace');renderBoard();}else if(cfg.workspaces&&cfg.mode!=='general'){state=null;gallery=await api(cfg.customer?'customer_projects':'customers');renderCustomerSpaces();}else{gallery=await api('gallery');state=null;renderGallery();}}catch(e){note(e.message);root.replaceChildren(el('p','cb-empty',e.message),link('Boards','boards.php'));}finally{root.setAttribute('aria-busy','false');updateWorkspaceTabs();if(liveSync&&state?.board)liveSync.seed(state);}}
async function save(action,d={},reload=true){if(busy)throw new Error('A save is already in progress.');busy=true;try{if(state?.personal){if(action!=='move_card')throw new Error('Use card details to edit this task.');const ids=state.cards.filter(c=>Number(c.fk_list)===Number(d.list)&&Number(c.fk_task)!==Number(d.task));const before=ids[Number(d.position)]?.fk_task||0;const response=await fetch('personal_action.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({token:cfg.token,action:'move',task_id:d.task,version:state.board.version,payload:JSON.stringify({column:Number(d.list),before})})});const r=await response.json();if(!response.ok||!r.ok)throw new Error(r.message);await load();return r;}const result=await api(action,Object.assign({board:cfg.board,version:state?.board.version},d));note('Saved');if(reload)await load();return result;}finally{busy=false;}}
