function backgroundInk(hex){if(!/^#[0-9a-f]{6}$/i.test(hex||''))return '#fff';const c=hex.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return .2126*c[0]+.7152*c[1]+.0722*c[2]>.179?'#000':'#fff';}
