 let objectUrl=null;const mode=f.querySelector('[name=background_mode]'),color=f.querySelector('[name=background]');const update=()=>{label.hidden=mode.value!=='image';color.closest('label').hidden=mode.value!=='color';preview.style.backgroundColor=color.value;preview.style.backgroundImage=mode.value==='image'?(objectUrl?'url("'+objectUrl+'")':b.background_image?'url("board_background.php?board='+Number(b.rowid)+'&v='+encodeURIComponent(b.background_image)+'")':'none'):'none';};
