function projectDeadline(p){const value=p.deadline||{},wrap=el('div','cb-project-deadline');if(!value.date){wrap.append(el('small','',wsText('بدون موعد نهائي','No deadline')));return wrap;}const date=el('time','',wsText('الموعد: ','Deadline: ')+value.display);date.setAttribute('datetime',value.date);wrap.append(date);const names={urgent:wsText('الموعد: عاجل','Deadline: Urgent'),overdue:wsText('الموعد: متأخر','Deadline: Overdue'),completed:wsText('المشروع مكتمل','Project completed')};if(names[value.indicator])wrap.append(el('span','cb-ws-priority cb-deadline-'+value.indicator,names[value.indicator]));return wrap;}
