/* M116 cash card summaries — independently finance-authorized, no totals in board payload. */
let accountSummaryQueue=[],accountSummaryScheduled=false;
function accountCardSummary(card,customer,project=0){
 if(!cfg.accountStatements)return;
 const node=el('div','cb-board-counts');card.append(node);accountSummaryQueue.push({node,scope:{customer:Number(customer),project:Number(project)}});
 if(!accountSummaryScheduled){accountSummaryScheduled=true;queueMicrotask(flushAccountCardSummaries);}
}
async function flushAccountCardSummaries(){
 const items=accountSummaryQueue;accountSummaryQueue=[];accountSummaryScheduled=false;
 const money=v=>{let n=BigInt(v),neg=n<0n;if(neg)n=-n;return(neg?'−':'')+(n/100n).toLocaleString('en-US')+'.'+String(n%100n).padStart(2,'0');};
 const bidi=text=>{const n=el('bdi','',text);n.dir='ltr';return n;};
 for(let at=0;at<items.length;at+=20){const batch=items.slice(at,at+20).filter(x=>x.node.isConnected);if(!batch.length)continue;
  try{const response=await fetch('account_summary.php?'+new URLSearchParams({scopes:batch.map(x=>[x.scope.customer,x.scope.project,0].join(':')).join(',')}),{cache:'no-store'});if(!response.ok)throw Error('Unavailable');const data=await response.json();if(!data.ok||!Array.isArray(data.summaries)||data.summaries.length!==batch.length)throw Error('Unavailable');
   batch.forEach((item,i)=>{const r=data.summaries[i];if(!item.node.isConnected)return;if(!r.available||r.scope.customer!==item.scope.customer||r.scope.project!==item.scope.project){item.node.remove();return;}const v=r.totals;
    const balance=el('strong','',wsText('الرصيد: ','Balance: ')),due=el('div','',wsText('المطلوب لتغطية المصروفات: ','Due: '));balance.append(bidi(money(v.balance_minor)+' '+v.base_currency));due.append(bidi(money(v.due_minor)+' '+v.base_currency));item.node.replaceChildren(balance,due);
    const positions=Object.entries(v.currencies);if(positions.length){const originals=el('small','',wsText('العملات الأصلية: ','Original currencies: '));positions.forEach(([cur,pos],j)=>{if(j)originals.append(el('span','',' · '));originals.append(bidi(cur),el('span','',wsText(' رصيد ',' balance ')),bidi(money(pos.balance_minor)),el('span','',wsText(' / مطلوب ',' / due ')),bidi(money(pos.due_minor)));});item.node.append(originals);}
   });
  }catch{batch.forEach(x=>x.node.remove());}
 }
}
/* End M116 cash card summaries */
