  const listScroll=[...root.querySelectorAll('.cb-list')].map(n=>({id:n.dataset.list,top:n.scrollTop,left:n.scrollLeft}));
  const task=a?.closest('.cb-card')?.dataset.task,kind=a?.matches('.cb-card-title')?'.cb-card-title':a?.matches('.cb-card-handle')?'.cb-card-handle':a?.matches('.cb-card-menu')?'.cb-card-menu':null;
