  status:(value,stats)=>{const words={live:wsText('متصل','Connected'),waiting:wsText('التحديث ينتظر انتهاء التحرير أو السحب','Update waiting for editing or dragging to finish'),offline:wsText('الاتصال منقطع؛ ستتم إعادة المحاولة','Connection interrupted; retrying'),denied:wsText('توقّف التحديث لحماية صلاحيات الوصول','Updates stopped to protect access')};phase.textContent=words[value]||value;time.textContent=wsText('فحص كل ثانيتين · ','Polling every 2 seconds · ')+new Date().toLocaleTimeString(cfg.lang==='ar'?'ar-EG':'en-GB');monitor.dataset.phase=value;monitor.dataset.checks=stats.checks;monitor.dataset.applied=stats.applied;monitor.dataset.lastAppliedAt=stats.lastAppliedAt||'';monitor.dataset.roundTripMs=stats.lastRoundTripMs??'';}
